{
  "action": "final",
  "output": {
    "research_concepts": [
      "defensive adjustment",
      "halftime opponent scoring change",
      "H2-H1 difference",
      "team trait reliability",
      "second half suppression",
      "defensive consistency"
    ],
    "methodological_questions": [
      "sample size per team per season",
      "reliability of intra-game change metrics",
      "confounding by game script and opponent quality",
      "regression to the mean in half-to-half changes",
      "measurement stability across seasons",
      "floor and ceiling effects"
    ],
    "historical_evidence": [
      {
        "id": "FAM:SF-APPS-076",
        "status_as_recorded": "rejected",
        "finding": "Trigger attribution: variance of H1->H2 PPP collapse. RTM (ppp_h1 alone) explains 32.9% of variance; usage +0.0%, process+shot-zone +1.7%, lineup +0.0%, context +0.0%. Unexplained 65.4% is idiosyncratic noise from small per-half n. Total explained 34.6%, with RTM contributing 95% of that."
      },
      {
        "id": "FAM:SF-APPS-070",
        "status_as_recorded": "rejected",
        "finding": "H1 usage as predictor of H2 suppression. After controlling for RTM, BH-adjusted tests show null or weak effects; top-1 accuracy only +0.039 over mean-reversion baseline (0.550 vs 0.511); bulk of H2 suppression is RTM."
      },
      {
        "id": "FAM:SF-APPS-025",
        "status_as_recorded": "untestable",
        "finding": "Adapt vs continue matched-pair overall-offense excess post-hoc. Group B (abandon suppressed play type) CI includes 0 (p=0.386, n=255 clusters=242); post-hoc cohort reconstruction; placebo dependence."
      }
    ],
    "failed_approaches": [
      {
        "id": "FAM:SF-APPS-076",
        "what_failed": "Attempt to attribute H1‑to‑H2 PPP collapse to observable in‑game changes beyond regression to the mean.",
        "why": "RTM already explains 32.9% of variance; process, usage, shot zone, lineup, and context add only ~1.7 pp together; 65.4% of the variance remains unexplained idiosyncratic noise."
      },
      {
        "id": "FAM:SF-APPS-070",
        "what_failed": "Using first‑half play‑type usage to predict second‑half suppression (distribution shift hypothesis).",
        "why": "After BH correction, matched ATT does not survive; predictive lift over mean‑reversion baseline is only +0.039 (accuracy 0.550 vs 0.511). The bulk of H2 suppression is RTM."
      },
      {
        "id": "FAM:SF-APPS-025",
        "what_failed": "Post‑hoc test comparing teams that abandoned a suppressed play type (h2_n≤1) vs continued (h2_n≥5) on overall offense H1→H2 excess decline.",
        "why": "Group B (abandon) CI includes zero at primary caliper (p=0.386, n=255); the cohort is a reconstructed post‑hoc group not validated as successful adaptation; flagged for PLACEBO_DEPENDENCE and low SAMPLE_SIZE_POWER."
      }
    ],
    "evidence_establishes": [
      "H1‑to‑H2 change in opponent points per possession, measured at the play‑type level, is dominated by regression to the mean and large residual noise; systematic variation attributable to in‑game process, usage, or lineup is negligible.",
      "Attempts to find a systematic signal beyond RTM in second‑half suppression have yielded adequately powered null results.",
      "Ad‑hoc designs that rely on small, reconstructed groups fail to produce reliable results and suffer from placebo dependence."
    ],
    "evidence_does_not_establish": [
      "Whether the overall team defensive effect on opponent H2‑H1 scoring change (not limited to play types) contains a stable, cross‑game or cross‑season signal.",
      "Direct estimates of intra‑class correlation or year‑over‑year stability of a team‑level H2‑H1 differential.",
      "How much RTM and noise would remain after controlling for H1 opponent performance and opponent strength in a whole‑team framework."
    ],
    "own_inferences": [
      "The strong RTM and noise documented for play‑type PPP almost certainly carry over to the overall H2‑H1 point differential; any true team defensive adjustment trait is likely to be very small relative to within‑game variance.",
      "With only 82 games per team per season and 4 seasons (120 team‑seasons), the ability to detect a small intra‑class correlation or a stable year‑over‑year effect is low.",
      "Roster turnover across seasons further undermines the idea of a persistent team trait, making year‑over‑year correlations an even weaker test."
    ],
    "uncertainties": [
      "The exact magnitude of a possible aggregate team defensive effect after accounting for RTM and opponent quality is unknown.",
      "Whether averaging across all play types reduces noise enough to reveal a small but real signal that was undetectable at the play‑type level.",
      "The optimal adjustment for RTM (e.g., controlling for H1 points or efficiency) without absorbing the very trait of interest."
    ],
    "historical_effect": {
      "changed_decision": "yes",
      "explanation": "Without historical evidence, one might assume that H2‑H1 change could be a stable team trait worth testing with 120 team‑seasons. The retrieved studies show that almost all half‑to‑half variation in opponent efficiency is RTM and noise, and that design attempts to isolate a systematic component have failed. This strongly suggests that a test of reliability would be underpowered, likely to yield a null or a spurious result from uncontrolled RTM, and thus the decision shifts from proceed to do_not_proceed."
    },
    "testability": {
      "p_testable": 0.3,
      "blocking_constraints": [
        {
          "code": "RTM_SELECTION",
          "text": "H2‑H1 change is mechanically correlated with H1 performance; teams with extreme first halves will regress, creating spurious stability if not fully controlled."
        },
        {
          "code": "MEASURE_RELIABILITY",
          "text": "Half‑game scoring is intrinsically noisy; the reliability of a single‑game H2‑H1 difference is low, limiting the precision of a team‑level average even over 82 games."
        },
        {
          "code": "SAMPLE_SIZE_POWER",
          "text": "With only 30 teams per season and 4 seasons, year‑over‑year correlations will have large standard errors, and split‑half reliability within a season will be modest."
        },
        {
          "code": "CONFOUNDING",
          "text": "Opponent strength, game location, rest, and roster turnover across seasons confound any attempt to measure a stable team defensive trait."
        }
      ]
    },
    "prior_work": {
      "already_answered": "partly",
      "cited": [
        "FAM:SF-APPS-076",
        "FAM:SF-APPS-070"
      ],
      "summary": "Prior work on within‑game tactical adaptation and H2 suppression shows that regression to the mean and irreducible noise dominate half‑to‑half changes in opponent efficiency. While these studies did not directly test the reliability of a team‑level H2‑H1 differential as a stable trait, their null results and variance decompositions make the proposed hypothesis highly implausible."
    },
    "risks": [
      {
        "code": "RTM_SELECTION",
        "text": "Teams that face extreme first‑half scoring will regress toward their seasonal mean in the second half, producing differences that are correlated over games if team opponent quality is persistent, falsely suggesting a reliable effect."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "H2‑H1 change per game has a large random component; the expected signal‑to‑noise ratio for a team trait is low even before considering RTM."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Year‑over‑year reliability estimates would be based on at most 4 data points per team (fewer after roster changes), yielding wide confidence intervals and low power to detect a meaningful intraclass correlation."
      },
      {
        "code": "CONFOUNDING",
        "text": "Differences in schedule strength, home/road splits, injuries, and roster continuity across seasons make it difficult to attribute stability solely to a persistent defensive scheme."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "Testing multiple operationalisations (points per game, per‑possession, different halves of the season, several reliability coefficients) inflates the risk of a false positive."
      }
    ],
    "predicted_outcome": {
      "supported": 0.05,
      "rejected": 0.40,
      "untestable": 0.20,
      "artifact": 0.30,
      "uncertain": 0.05
    },
    "decision": "do_not_proceed",
    "design": {
      "estimand": "Intraclass correlation (ICC) and year‑over‑year Pearson correlation of team‑level mean opponent points per possession differential (H2 minus H1), after adjusting for H1 opponent PPP and opponent season offensive rating.",
      "unit": "Team‑season (30 teams × 4 seasons = 120 team‑seasons)",
      "sample": "All regular season games from 2022‑23 through 2025‑26, excluding games that went to overtime (to keep halves of equal length) and games with a halftime margin >25 points (optional sensitivity check).",
      "power": "With 30 teams and 4 seasons, the standard error of an ICC close to zero is large; a true ICC of 0.1 would have approximately 30% power to be detected as significantly >0 at α=0.05.",
      "controls": "H1 opponent points per possession, opponent season offensive rating, home/away indicator, second night of back‑to‑back, and an interaction between H1 PPP and opponent rating to reduce RTM contamination.",
      "falsification": "Permutation test of team labels within each season to build the null distribution of the split‑half correlation; also compare observed year‑over‑year correlation with that from a simulation where true team effects are zero and RTM is the only mechanism.",
      "multiplicity": "Plan to report only one primary reliability metric (ICC of team‑means across seasons) and use Bonferroni correction if exploratory sub‑analyses are presented.",
      "decision_rule": "Conclude that the effect is a reliable trait only if the ICC point estimate > 0.05 and the lower bound of the one‑sided 95% CI exceeds 0.00; otherwise the data will be taken as insufficient to claim reliability.",
      "data_version": "NBA per‑game data as of 2026‑10‑06, using play‑by‑play and box‑score derived per‑possession statistics for the 2022‑23 through 2025‑26 seasons."
    }
  }
}

